const extraItems=[
{id:'bunny',name:'Little rabbit',type:'Characters',price:0,desc:'Long ears, a curious heart, and a soft knitted sweater.'},
{id:'cat',name:'Moonbeam cat',type:'Characters',price:90,desc:'A thoughtful little cat who loves books and quiet corners.'},
{id:'fox',name:'Maple fox',type:'Characters',price:120,desc:'A warm woodland companion for cabin adventures.'},
{id:'bear',name:'Cocoa bear',type:'Characters',price:100,desc:'A gentle lodge companion with round velvet ears.'},
{id:'alien',name:'Orbit friend',type:'Characters',price:140,desc:'A green antenna-topped visitor, perfectly at home among the stars.'},
{id:'library',name:'The enchanted library',type:'Rooms',price:0,premium:true,desc:'Tall bookcases, framed portraits, warm woodwork and collected treasures.'},
{id:'garden',name:'The glasshouse atelier',type:'Rooms',price:0,premium:true,desc:'An intricate botanical hideaway with climbing vines and flowering pots.'}
];
function renameCharacter(){showModal(`<div class="eyebrow">A NAME THAT FEELS LIKE HOME</div><h2>Meet… whoever you imagine.</h2><p>Rename your companion any time. Always free.</p><form id="name-form"><label class="field-label" for="new-name">Your companion’s name</label><input id="new-name" maxlength="24" required value="${escapeHTML(state.characterName)}"><div class="modal-actions"><button class="primary">Save name · Free</button></div></form>`);$('#name-form').onsubmit=e=>{e.preventDefault();const name=$('#new-name').value.trim();if(!name)return;state.characterName=name;save();modal.close();render();toast('Hello, '+name+' ♡')}}
function premium(){content.innerHTML=greeting('A little extra wonder.','Optional extras. Your everyday care and games stay free.','MELLOW PLUS')+`<div class="premium-hero card"><div class="eyebrow">THE COLLECTOR’S CORNER</div><h2>More worlds to get lost in.</h2><p>Intricate rooms, special accessories, and optional coin packs.</p><div class="premium-options"><div><b>✧ Mellow Plus</b><p>Exclusive rooms and seasonal customization collections.</p></div><div><b>✦ Coin packs</b><p>Optional extra coins. Never required for care features or games.</p></div></div><div class="notice">Apple in-app purchases planned · Preview only. Purchases are unavailable in this web prototype. No card information is collected and nothing can be charged.</div><button class="primary" id="adult-info">Parent / guardian purchase information</button></div><div class="view-grid" style="margin-top:24px">${items.filter(i=>curatedIds.has(i.id)&&i.premium).map(i=>`<section class="card"><canvas class="preview-world" data-plus="${i.id}" width="960" height="620"></canvas><div class="shop-item"><div class="eyebrow">PLUS COLLECTION · PREVIEW</div><h3>${i.name}</h3><p>${i.desc}</p><button class="secondary" disabled>Checkout not configured</button></div></section>`).join('')}</div>`;document.querySelectorAll('[data-plus]').forEach(c=>{const i=items.find(x=>x.id===c.dataset.plus);paintWorld(c,i.type==='Rooms'?i.id:(state.equipped.Rooms||'cozy'),previewEquipment(i),'range','Reading',true,!['Rooms','Themes'].includes(i.type))});$('#adult-info').onclick=()=>showModal(`<div class="eyebrow">ADULT-APPROVED PURCHASES</div><h2>No accidental checkout.</h2><p>Payments are not enabled in this prototype. The iPhone/iPad app will need StoreKit in-app purchases and verified App Store transactions before granting items or coins. This web preview cannot initiate Apple purchases.</p><div class="notice">A local PIN or age checkbox is not proof of adult authorization. For children, parents should configure Family Sharing Ask to Buy and purchase restrictions. Pending approval grants nothing. Pricing, subscription renewal, restore purchases, and cancellation must be clear before launch.</div><button class="primary" disabled>Secure checkout unavailable</button>`)}
let gameType=null,gameLevel=1,bridge=[],shapeBoard=[],shapeSelected=0,shapeRotation=0,sortTubes=[],sortSelected=null,sortHistory=[];
const pieces=[[[0,0],[1,0],[2,0],[3,0]],[[0,0],[0,1],[0,2],[1,2]],[[0,0],[0,1],[0,2],[1,2]],[[0,0],[1,0],[0,1],[1,1]]];
const gameColors=['#be92cb','#85b8aa','#e7bd7e','#dd9eb2'];
function games(){content.innerHTML=greeting('Little puzzles. Happy paws.','Build, fit, and sort with '+escapeHTML(state.characterName)+'. Play at your own pace.','THE PLAYROOM')+`<div class="game-catalog">${[['bridge','🌉','Bridge builder','Choose planks to span a river. Plan your length and help your companion cross.'],['shapes','🧩','Shape studio','Rotate and fit four different pieces inside a little 4 × 4 frame.'],['sort','🧪','Color garden','Pour matching colors into bottles until each one holds a single color.']].map(([id,icon,title,desc])=>`<button class="card game-tile" data-game="${id}"><span>${icon}</span><h2>${title}</h2><p>${desc}</p><small>Play together →</small></button>`).join('')}</div><section id="game-stage" class="card game-stage"><p>Choose a little adventure above. First completion of each puzzle per day earns 15 coins.</p></section>`;document.querySelectorAll('[data-game]').forEach(b=>b.onclick=()=>startGame(b.dataset.game));if(gameType)drawGame()}
function startGame(type){gameType=type;bridge=[];shapeBoard=Array(16).fill(-1);shapeSelected=0;shapeRotation=0;sortTubes=[['a','b','a','b'],['b','c','b','c'],['c','a','c','a'],[],[]];sortSelected=null;sortHistory=[];drawGame()}
function gameReward(key){const id=new Date().toLocaleDateString('en-CA')+':'+key;if(state.gameWins.includes(id))return false;state.gameWins.push(id);state.coins+=15;save();return true}
function winGame(key){celebrationUntil=Date.now()+3500;const fresh=gameReward(key);$('#game-feedback').textContent='Wonderful! '+state.characterName+' made it. '+(fresh?'+15 coins ✦':'You’ve already collected today’s reward for this puzzle.');$('#game-stage').classList.add('game-won')}
function rotatePiece(p,turns){let cells=p.map(([x,y])=>[x,y]);for(let i=0;i<turns%4;i++)cells=cells.map(([x,y])=>[-y,x]);const minX=Math.min(...cells.map(c=>c[0])),minY=Math.min(...cells.map(c=>c[1]));return cells.map(([x,y])=>[x-minX,y-minY])}
function placeShape(index){const used=shapeBoard.includes(shapeSelected);if(used){shapeBoard=shapeBoard.map(v=>v===shapeSelected?-1:v);return false}const x=index%4,y=Math.floor(index/4),cells=rotatePiece(pieces[shapeSelected],shapeRotation).map(([dx,dy])=>[x+dx,y+dy]);if(cells.some(([xx,yy])=>xx<0||xx>=4||yy<0||yy>=4||shapeBoard[yy*4+xx]!==-1))return false;cells.forEach(([xx,yy])=>shapeBoard[yy*4+xx]=shapeSelected);return true}
function pour(from,to){if(from===to||!sortTubes[from].length||sortTubes[to].length===4)return false;const color=sortTubes[from].at(-1);if(sortTubes[to].length&&sortTubes[to].at(-1)!==color)return false;sortHistory.push(sortTubes.map(t=>[...t]));let count=0;for(let i=sortTubes[from].length-1;i>=0&&sortTubes[from][i]===color;i--)count++;const amount=Math.min(count,4-sortTubes[to].length);sortTubes[from].splice(-amount);sortTubes[to].push(...Array(amount).fill(color));return true}
function sortSolved(){return sortTubes.every(t=>t.length===0||(t.length===4&&t.every(c=>c===t[0])))}
function drawGame(){const el=$('#game-stage');if(!el)return;el.classList.remove('game-won');const title=gameType==='bridge'?'A bridge to the other side':gameType==='shapes'?'A place for every piece':'A little color harmony';el.innerHTML=`<div class="game-top"><div><div class="eyebrow">${escapeHTML(state.characterName)}’S LITTLE ADVENTURE</div><h2>${title}</h2></div><button class="secondary" id="reset-game">Start over</button></div><canvas id="game-pet" width="480" height="310" aria-label="Your selected companion"></canvas><div id="game-board"></div><p id="game-feedback" role="status"></p>`;paintWorld($('#game-pet'),state.equipped.Rooms||'cozy',state.equipped,'range','Dancing',true,true);$('#reset-game').onclick=()=>startGame(gameType);
if(gameType==='bridge'){const target=[7,9,11][gameLevel-1],sum=bridge.reduce((a,b)=>a+b,0);$('#game-board').innerHTML=`<p>Span ${target} units with at most 4 planks. Level ${gameLevel} / 3.</p><div class="river"><span>🏁</span><div class="planks">${bridge.map(n=>`<i style="flex:${n}">${n}</i>`).join('')}</div><span>🌳</span></div><p>${sum} / ${target} units · ${bridge.length} / 4 planks</p><div class="game-controls">${[1,2,3].map(n=>`<button class="secondary" data-plank="${n}">+ ${n}-unit plank</button>`).join('')}<button class="secondary" id="bridge-undo">Undo</button><button class="primary" id="cross-bridge">Cross bridge →</button><button class="secondary" id="bridge-next">Next level</button></div>`;document.querySelectorAll('[data-plank]').forEach(b=>b.onclick=()=>{if(bridge.length<4){bridge.push(Number(b.dataset.plank));drawGame()}});$('#bridge-undo').onclick=()=>{bridge.pop();drawGame()};$('#cross-bridge').onclick=()=>{if(sum===target&&bridge.length<=4)winGame('bridge-'+gameLevel);else $('#game-feedback').textContent='The bridge needs exactly '+target+' units. Try adjusting your planks.'};$('#bridge-next').onclick=()=>{gameLevel=gameLevel%3+1;bridge=[];drawGame()}}
if(gameType==='shapes'){$('#game-board').innerHTML=`<p>Select a piece, rotate it, then tap a cell to place its top-left corner. Select a placed piece and tap the board to remove it.</p><div class="shape-picker">${pieces.map((p,i)=>`<button class="secondary ${shapeSelected===i?'selected':''}" data-piece="${i}">Piece ${i+1} ${['━━━━','┗','┗','▣'][i]}</button>`).join('')}<button class="secondary" id="rotate-shape">Rotate ↻</button></div><div class="shape-preview">${rotatePiece(pieces[shapeSelected],shapeRotation).map(([x,y])=>`<i style="left:${x*19}px;top:${y*19}px;background:${gameColors[shapeSelected]}"></i>`).join('')}</div><div class="shape-grid">${shapeBoard.map((v,i)=>`<button aria-label="Row ${Math.floor(i/4)+1}, column ${i%4+1}${v>=0?', piece '+(v+1):', empty'}" data-cell="${i}" style="background:${v<0?'#f5ecf7':gameColors[v]}">${v<0?'':v+1}</button>`).join('')}</div>`;document.querySelectorAll('[data-piece]').forEach(b=>b.onclick=()=>{shapeSelected=Number(b.dataset.piece);shapeRotation=0;drawGame()});$('#rotate-shape').onclick=()=>{shapeRotation++;drawGame()};document.querySelectorAll('[data-cell]').forEach(b=>b.onclick=()=>{const ok=placeShape(Number(b.dataset.cell));drawGame();if(shapeBoard.every(v=>v>=0))winGame('shapes');else if(!ok)$('#game-feedback').textContent='Piece removed, or that spot doesn’t fit. Try rotating or another cell.'})}
if(gameType==='sort'){$('#game-board').innerHTML=`<p>Select a bottle, then a destination. Only matching top colors can be poured. Four layers fill a bottle.</p><div class="bottles">${sortTubes.map((tube,i)=>`<button data-tube="${i}" class="bottle ${sortSelected===i?'selected':''}" aria-label="Bottle ${i+1}, bottom to top: ${tube.join(', ')||'empty'}">${Array.from({length:4},(_,j)=>`<span style="background:${({a:'#b995d0',b:'#8ebfb0',c:'#e7bd87'})[tube[3-j]]||'transparent'}">${tube[3-j]||''}</span>`).join('')}</button>`).join('')}</div><button class="secondary" id="sort-undo">Undo pour</button>`;document.querySelectorAll('[data-tube]').forEach(b=>b.onclick=()=>{const to=Number(b.dataset.tube);if(sortSelected===null)sortSelected=to;else{pour(sortSelected,to);sortSelected=null}drawGame();if(sortSolved())winGame('sort')});$('#sort-undo').onclick=()=>{if(sortHistory.length)sortTubes=sortHistory.pop();sortSelected=null;drawGame()}}
}
